from django.conf import settings
from django.db import models
from django.utils import timezone

from assignments.models import Assignment
from forms.models import FormVersion

from .guard import GuardedModel


class Status(models.TextChoices):
    DRAFT = "draft", "Draft"
    SUBMITTED = "submitted", "Submitted"
    APPROVED = "approved", "Approved"
    RETURNED = "returned", "Returned"


class Submission(GuardedModel):
    """One inspection. The id is generated by the client, so the same id is used on the device, in
    the outbox and here from the very first save (ADR 0001).

    Never write this model directly. Every change goes through `sync.services` so that the advisory
    lock, the version bump, the ledger row and the event row all happen. The database backs that
    up: a trigger rejects any UPDATE that does not raise `version` by exactly 1 and `server_seq`
    strictly.
    """

    id = models.UUIDField(primary_key=True, editable=False)
    assignment = models.ForeignKey(Assignment, on_delete=models.PROTECT, related_name="submissions")
    # Pinned for life: the assignment's form version, immutable (trigger).
    form_version = models.ForeignKey(
        FormVersion, on_delete=models.PROTECT, related_name="submissions"
    )
    data = models.JSONField(default=dict)
    status = models.CharField(max_length=16, choices=Status.choices, default=Status.DRAFT)
    # Counts accepted changes, starting at 1 on creation.
    version = models.PositiveIntegerField(default=1)
    # field name -> the version that last changed it; drives field-level conflict detection.
    field_versions = models.JSONField(default=dict)
    # Position in the pull feed. Taken from a sequence while holding the advisory lock.
    server_seq = models.BigIntegerField(unique=True)
    deleted_at = models.DateTimeField(null=True, blank=True)
    updated_by = models.ForeignKey(
        settings.AUTH_USER_MODEL, on_delete=models.PROTECT, null=True, related_name="+"
    )
    created_at = models.DateTimeField(default=timezone.now)
    updated_at = models.DateTimeField(default=timezone.now)

    class Meta:
        constraints = [
            models.CheckConstraint(
                condition=models.Q(status__in=[s.value for s in Status]),
                name="submissions_submission_status_valid",
            ),
            models.CheckConstraint(
                condition=models.Q(version__gte=1), name="submissions_submission_version_gte_1"
            ),
        ]
        indexes = [models.Index(fields=["assignment"], name="submissions_assignment_idx")]

    def __str__(self) -> str:
        return f"{self.id} v{self.version} {self.status}"


class EventKind(models.TextChoices):
    CREATED = "created"
    UPDATED = "updated"
    SUBMITTED = "submitted"
    DELETED = "deleted"
    RESTORED = "restored"
    APPROVED = "approved"
    RETURNED = "returned"
    ADMIN_EDITED = "admin_edited"
    CONFLICT = "conflict"
    REJECTED = "rejected"


class SubmissionEvent(GuardedModel):
    """Append-only history of what happened to a submission: the audit trail, and the source of
    the admin conflict log in v1. Rows can never be changed or deleted (grants and a trigger)."""

    submission = models.ForeignKey(Submission, on_delete=models.PROTECT, related_name="events")
    # Version after an applied change, or the current version for a conflict or rejection.
    version = models.PositiveIntegerField()
    kind = models.CharField(max_length=16, choices=EventKind.choices)
    actor = models.ForeignKey(
        settings.AUTH_USER_MODEL, on_delete=models.PROTECT, null=True, related_name="+"
    )
    mutation_id = models.UUIDField(null=True, blank=True)
    detail = models.JSONField(default=dict)
    created_at = models.DateTimeField(default=timezone.now)

    class Meta:
        constraints = [
            models.CheckConstraint(
                condition=models.Q(kind__in=[k.value for k in EventKind]),
                name="submissions_event_kind_valid",
            ),
        ]
        indexes = [models.Index(fields=["submission", "id"], name="submissions_event_sub_idx")]
        ordering = ["id"]

    def __str__(self) -> str:
        return f"{self.kind} on {self.submission_id} (v{self.version})"
